package oval

import (
	"reflect"
	"testing"

	"github.com/future-architect/vuls/models"
	ovalmodels "github.com/vulsio/goval-dictionary/models"
)

func TestPackNamesOfUpdate(t *testing.T) {
	var tests = []struct {
		in       models.ScanResult
		defPacks defPacks
		out      models.ScanResult
	}{
		{
			in: models.ScanResult{
				ScannedCves: models.VulnInfos{
					"CVE-2000-1000": models.VulnInfo{
						AffectedPackages: models.PackageFixStatuses{
							{Name: "packA"},
							{Name: "packB", NotFixedYet: false},
						},
					},
				},
			},
			defPacks: defPacks{
				def: ovalmodels.Definition{
					Advisory: ovalmodels.Advisory{
						Cves: []ovalmodels.Cve{
							{
								CveID: "CVE-2000-1000",
							},
						},
					},
				},
				binpkgFixstat: map[string]fixStat{
					"packB": {
						notFixedYet: true,
						fixedIn:     "1.0.0",
					},
				},
			},
			out: models.ScanResult{
				ScannedCves: models.VulnInfos{
					"CVE-2000-1000": models.VulnInfo{
						AffectedPackages: models.PackageFixStatuses{
							{Name: "packA"},
							{Name: "packB", NotFixedYet: true},
						},
					},
				},
			},
		},
		{
			in: models.ScanResult{
				ScannedCves: models.VulnInfos{
					"CVE-2000-1000": models.VulnInfo{
						AffectedPackages: models.PackageFixStatuses{
							{Name: "packA"},
						},
					},
					"CVE-2000-1001": models.VulnInfo{
						AffectedPackages: models.PackageFixStatuses{
							{Name: "packC"},
						},
					},
				},
			},
			defPacks: defPacks{
				def: ovalmodels.Definition{
					Advisory: ovalmodels.Advisory{
						Cves: []ovalmodels.Cve{
							{
								CveID: "CVE-2000-1000",
							},
							{
								CveID: "CVE-2000-1001",
							},
						},
					},
				},
				binpkgFixstat: map[string]fixStat{
					"packB": {
						notFixedYet: false,
					},
				},
			},
			out: models.ScanResult{
				ScannedCves: models.VulnInfos{
					"CVE-2000-1000": models.VulnInfo{
						AffectedPackages: models.PackageFixStatuses{
							{Name: "packA"},
							{Name: "packB", NotFixedYet: false},
						},
					},
					"CVE-2000-1001": models.VulnInfo{
						AffectedPackages: models.PackageFixStatuses{
							{Name: "packB", NotFixedYet: false},
							{Name: "packC"},
						},
					},
				},
			},
		},
	}

	// util.Log = util.Logger{}.NewCustomLogger()
	for i, tt := range tests {
		RedHat{}.update(&tt.in, tt.defPacks)
		for cveid := range tt.out.ScannedCves {
			e := tt.out.ScannedCves[cveid].AffectedPackages
			a := tt.in.ScannedCves[cveid].AffectedPackages
			if !reflect.DeepEqual(a, e) {
				t.Errorf("[%d] expected: %v\n  actual: %v\n", i, e, a)
			}
		}
	}
}
